(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,97677,e=>{"use strict";let t="2026-10-29",n=[{id:"revolution-and-independence",periodId:"revolution",title:"Revolution and Independence",subtitle:"From Imperial Crisis to the United States Constitution",years:"1763–1789",estimatedHours:"6–8 hours",heroImage:"/images/declaration-of-independence.jpg",heroAlt:"John Trumbull's painting Declaration of Independence",deepDiveNote:"Full-length lectures from Yale’s free open courses, mostly Joanne Freeman’s The American Revolution (HIST 116).",summary:"Trace how thirteen British colonies moved from imperial loyalty after the Seven Years’ War to armed revolution, declared universal principles of human equality while grappling with the contradiction of slavery, and forged a durable federal republic in Philadelphia.",modules:[{id:"imperial-crisis",shortTitle:"Roots of Rebellion",number:1,title:"Roots of Rebellion & the Imperial Crisis",years:"1450–1774",subtitle:"Indigenous confederacies, imperial war debt, and the road to colonial resistance",overview:"Long before Britain taxed colonial paper and tea, the Haudenosaunee Confederacy practiced council governance in North America. Britain’s victory in the French and Indian War (1754–1763) redrew the continent’s map, left London deeply in debt, and sparked a fierce constitutional dispute over parliamentary taxation, street clashes in Boston, and intercolonial union at Philadelphia.",guidingQuestion:"Why did Britain’s triumph in 1763 unravel its North American empire within a single decade?",entryIds:["haudenosaunee-confederacy","french-and-indian-war","stamp-act-crisis","boston-massacre","boston-tea-party","continental-congress"],primarySourceChallenge:{id:"psc-imperial-crisis",quote:"Facts are stubborn things; and whatever may be our wishes, our inclinations, or the dictates of our passions, they cannot alter the state of facts and evidence.",speaker:"John Adams",context:"Closing argument at the Boston Massacre trial, December 1770",prompt:"Why did future Patriot leader John Adams agree to defend the British soldiers accused of the Boston Massacre?",options:["He believed that in a free country every accused person deserves legal counsel and a verdict based strictly on evidence.","He had been appointed Royal Attorney General by Governor Thomas Hutchinson.","He wanted to delay the trial until the First Continental Congress could meet in Philadelphia.","He secretly supported the Townshend duties and the quartering of British regulars in Boston."],answer:0,entryId:"boston-massacre",historicalNote:"Adams risked his reputation in Boston to defend Captain Thomas Preston and eight British soldiers. Preston and six of the soldiers were acquitted; two were convicted of manslaughter and branded on the hand."},timeline:[{id:"t1-necessity",label:"George Washington surrenders at Fort Necessity",date:"July 1754",sort:1754.5,entryId:"french-and-indian-war"},{id:"t1-paris",label:"The Treaty of Paris ends the Seven Years’ War",date:"February 1763",sort:1763.1,entryId:"french-and-indian-war"},{id:"t1-stamp",label:"Parliament passes the Stamp Act",date:"March 1765",sort:1765.2,entryId:"stamp-act-crisis"},{id:"t1-declaratory",label:"Parliament repeals the Stamp Act and passes the Declaratory Act",date:"1766",sort:1766.2,entryId:"stamp-act-crisis"},{id:"t1-massacre",label:"British soldiers fire on a crowd on King Street, Boston",date:"March 5, 1770",sort:1770.2,entryId:"boston-massacre"},{id:"t1-tea",label:"Colonists dump 342 chests of tea into Boston Harbor",date:"December 16, 1773",sort:1773.95,entryId:"boston-tea-party"},{id:"t1-congress",label:"The First Continental Congress meets in Philadelphia",date:"September 5, 1774",sort:1774.7,entryId:"continental-congress"}],reflection:{modelAnswer:"Victory in 1763 left Britain with a doubled national debt and a much larger empire to govern. To pay for it, Parliament tightened enforcement and taxed the colonies directly, starting with the Sugar and Stamp Acts. Colonists, who believed that only their own elected assemblies could tax them and who feared that unchecked power corrupts, saw these laws as a threat to their liberty. Each round of resistance, from boycotts and the Stamp Act Congress to the Boston Tea Party, brought a harsher British response, and the Coercive Acts of 1774 finally pushed the colonies to act together in the First Continental Congress.",keyPoints:["The war’s cost and Britain’s new, larger empire","New taxes and enforcement after 1763","“No taxation without representation” and republican fears of corruption","Resistance methods: boycotts, congresses, crowd action","Escalation: the Coercive Acts united the colonies instead of isolating Boston"]},deepDive:[{url:"https://www.youtube.com/watch?v=8_ltTMQ6Gsg",title:"Being a British Colonist (Yale, The American Revolution, lecture 2, Joanne Freeman)",channel:"YaleCourses",views:204442,length:"39:30",checked:"2026-10-29"},{url:"https://www.youtube.com/watch?v=sbwOop46Dag",title:"Outraged Colonials: The Stamp Act Crisis (Yale lecture 5)",channel:"YaleCourses",views:132330,length:"41:10",checked:"2026-10-29"},{url:"https://www.youtube.com/watch?v=gGRW5nF2Mqs",title:"Resistance or Rebellion? (Or, What the Heck Is Happening in Boston?) (Yale lecture 6)",channel:"YaleCourses",views:113337,length:"46:44",checked:"2026-10-29"}],quiz:[{id:"m1-q1",context:"The Haudenosaunee Confederacy",prompt:"Which six Indigenous nations ultimately formed the Haudenosaunee (Iroquois) Confederacy under the Great Law of Peace?",options:["Mohawk, Oneida, Onondaga, Cayuga, Seneca, and Tuscarora","Cherokee, Chickasaw, Choctaw, Creek, Seminole, and Powhatan","Lakota, Cheyenne, Arapaho, Comanche, Kiowa, and Apache","Wampanoag, Narragansett, Pequot, Mohegan, Abenaki, and Huron"],answer:0,entryId:"haudenosaunee-confederacy",explanation:"Originally the Five Nations (Mohawk, Oneida, Onondaga, Cayuga, and Seneca), the confederacy became the Six Nations when the Tuscarora joined later."},{id:"m1-q2",context:"The French and Indian War",prompt:"What boundary did King George III’s Proclamation of 1763 establish after the French and Indian War?",options:["A line along the Appalachian Mountains restricting British colonial settlement to the east","The Mississippi River as the border between British Canada and Spanish Florida","The Ohio River as a permanent boundary between Virginia and Pennsylvania","The St. Lawrence River as a duty-free trade zone for colonial merchants"],answer:0,entryId:"french-and-indian-war",explanation:"To prevent costly frontier wars with Native nations after Pontiac’s War, the Proclamation of 1763 forbade colonial settlement west of the Appalachian Mountains, angering land speculators and settlers."},{id:"m1-q3",context:"The Stamp Act Crisis (1765)",prompt:"Why did the Stamp Act of 1765 provoke far wider colonial protest than earlier British trade duties?",options:["It was the first direct internal tax levied by Parliament on legal documents, newspapers, and everyday paper goods inside the colonies.","It banned all colonial ships from trading with ports in the Caribbean and Europe.","It abolished every colonial legislature and replaced elected governors with British generals.","It required every colonist to join the Church of England and pay tithes to London."],answer:0,entryId:"stamp-act-crisis",explanation:"Unlike external customs duties regulating imperial trade, the Stamp Act reached directly into colonial courts, ports, printing shops, and taverns to raise revenue without the consent of colonial assemblies."},{id:"m1-q4",context:"The Boston Massacre (1770)",prompt:"Which sailor of African and Indigenous descent, traditionally remembered as the first to fall, was killed when British soldiers fired on King Street on March 5, 1770?",options:["Crispus Attucks","Salem Poor","Peter Salem","James Armistead"],answer:0,entryId:"boston-massacre",explanation:"Crispus Attucks was among the five men killed as a result of the shooting on March 5, 1770, becoming an enduring symbol for both Patriots and later abolitionists."},{id:"m1-q5",context:"The Boston Tea Party & Continental Congress",prompt:"How did Parliament respond after the Sons of Liberty dumped 342 chests of East India Company tea into Boston Harbor in December 1773?",options:["By passing the Coercive (Intolerable) Acts, closing Boston’s port and altering Massachusetts’s charter, which spurred twelve colonies to convene the First Continental Congress.","By immediately repealing the Tea Act and granting Boston representation in the House of Commons.","By declaring war on France and blockading Philadelphia Harbor.","By ordering General George Washington to arrest Samuel Adams and John Hancock."],answer:0,entryId:"boston-tea-party",explanation:"Parliament’s Coercive Acts of 1774 were meant to isolate Massachusetts, but instead rallied twelve colonies (all except Georgia) to send delegates to the First Continental Congress in Philadelphia."}]},{id:"war-for-independence",shortTitle:"War for Independence",number:2,title:"Declaring & Winning Independence",years:"1775–1783",subtitle:"From the village green at Lexington to Independence Hall and the trenches of Yorktown",overview:"Armed conflict erupted in Massachusetts in April 1775, fourteen months before Congress voted to sever ties with Britain. Follow the military and political struggle across eight years of war: the drafting and adoption of the Declaration of Independence at Independence Hall, the alliances forged by American diplomats in Paris, and the Franco-American siege at Yorktown that forced British recognition of American sovereignty.",guidingQuestion:"How did an outnumbered Continental Army and a divided coalition of thirteen states defeat a global military superpower?",entryIds:["lexington-and-concord","battle-of-bunker-hill","common-sense","american-revolution","declaration-of-independence","independence-day","independence-hall","battles-of-saratoga","valley-forge","loyalists","siege-of-yorktown","treaty-of-paris-1783"],primarySourceChallenge:{id:"psc-war-for-independence",quote:"The clause too, reprobating the enslaving the inhabitants of Africa, was struck out in complaisance to South Carolina and Georgia, who had never attempted to restrain the importation of slaves, and who on the contrary still wished to continue it.",speaker:"Thomas Jefferson",context:"Recalling the Continental Congress’s July 1776 revisions to his draft of the Declaration of Independence",prompt:"What does Jefferson’s account reveal about the drafting of the Declaration of Independence in July 1776?",options:["Congress edited Jefferson’s draft for two days and removed his passage condemning the Atlantic slave trade to preserve unanimity with Deep South delegates.","The Continental Congress adopted Jefferson’s draft without changing a single word on July 2, 1776.","South Carolina and Georgia refused to sign the Declaration of Independence and walked out of Independence Hall.","King George III offered to abolish slavery in the colonies if Congress withdrew the Declaration."],answer:0,entryId:"declaration-of-independence",historicalNote:"After voting for independence on July 2, 1776, Congress revised Jefferson’s draft, striking his passage blaming King George III for the slave trade. Jefferson later wrote that it was cut to please South Carolina and Georgia. The final text was adopted on July 4."},timeline:[{id:"t2-lexington",label:"Fighting at Lexington and Concord",date:"April 19, 1775",sort:1775.3,entryId:"lexington-and-concord"},{id:"t2-army",label:"Congress creates the Continental Army under George Washington",date:"June 1775",sort:1775.45,entryId:"continental-congress"},{id:"t2-common",label:"Thomas Paine publishes Common Sense",date:"Early 1776",sort:1776.05,entryId:"common-sense"},{id:"t2-vote",label:"Congress votes for independence",date:"July 2, 1776",sort:1776.5,entryId:"declaration-of-independence"},{id:"t2-saratoga",label:"Burgoyne’s army surrenders at Saratoga",date:"October 17, 1777",sort:1777.8,entryId:"battles-of-saratoga"},{id:"t2-valley",label:"Washington’s army marches into Valley Forge",date:"December 19, 1777",sort:1777.97,entryId:"valley-forge"},{id:"t2-france",label:"France signs treaties with the United States",date:"February 6, 1778",sort:1778.1,entryId:"american-revolution"},{id:"t2-yorktown",label:"Cornwallis surrenders at Yorktown",date:"October 19, 1781",sort:1781.8,entryId:"siege-of-yorktown"},{id:"t2-paris",label:"The Treaty of Paris ends the war",date:"September 3, 1783",sort:1783.7,entryId:"treaty-of-paris-1783"}],reflection:{modelAnswer:"The Americans did not have to destroy the British army; they had to survive until Britain gave up. Washington learned to avoid battles that could wipe out his army and kept it in the field, so that capturing cities did not end the war. Militias controlled much of the countryside, and Britain, far from home, never had enough men to hold it. After Saratoga, France joined the war with money, soldiers, and a navy, turning a colonial rebellion into a global war that strained Britain everywhere. At Yorktown in 1781 a French fleet sealed off Cornwallis while American and French armies besieged him, and the loss of another army ended Britain’s will to keep fighting.",keyPoints:["Washington’s strategy of keeping the army intact","Britain’s difficulty holding territory far from home","The French alliance after Saratoga, and Spain and the Netherlands later","Yorktown: French naval power and a joint siege","Britain’s waning public support for an expensive war"]},deepDive:[{url:"https://www.youtube.com/watch?v=Dxdqdax4VbQ",title:"Common Sense (Yale, The American Revolution, lecture 10, Joanne Freeman)",channel:"YaleCourses",views:171322,length:"43:09",checked:"2026-10-29"},{url:"https://www.youtube.com/watch?v=sJU5wUK_loE",title:"Independence (Yale lecture 11)",channel:"YaleCourses",views:92092,length:"41:56",checked:"2026-10-29"},{url:"https://www.youtube.com/watch?v=W5j8TsHAzsA",title:"Who Were the Loyalists? (Yale lecture 9)",channel:"YaleCourses",views:99358,length:"45:51",checked:"2026-10-29"},{url:"https://www.youtube.com/watch?v=j81FTR63sRs",title:"The Logic of a Campaign (or, How in the World Did We Win?) (Yale lecture 17)",channel:"YaleCourses",views:67328,length:"46:50",checked:"2026-10-29"}],quiz:[{id:"m2-q1",context:"Battles of Lexington and Concord (1775)",prompt:"What was the objective of the British column that marched out of Boston on the night of April 18, 1775?",options:["To seize colonial gunpowder and military stores cached by the Massachusetts Provincial Congress at Concord","To capture the Continental Congress meeting at Independence Hall","To burn the port of Salem and impress colonial sailors into the Royal Navy","To relieve the besieged British garrison at Fort Ticonderoga"],answer:0,entryId:"lexington-and-concord",explanation:"General Thomas Gage sent about 700 regulars to seize colonial militia supplies at Concord, triggering the skirmish on Lexington Green and a fierce running fight at Concord’s North Bridge and along the Battle Road."},{id:"m2-q2",context:"Independence Day & The Declaration",prompt:"On what date did the Second Continental Congress actually vote to approve Richard Henry Lee’s resolution declaring the colonies free and independent states?",options:["July 2, 1776 (two days before adopting the final text of the Declaration on July 4)","April 19, 1775, immediately after the Battle of Lexington","August 2, 1776, when the engrossed parchment was first signed","September 3, 1783, when the Treaty of Paris was signed"],answer:0,entryId:"independence-day",explanation:"Congress voted for independence on July 2, 1776, the date John Adams predicted Americans would celebrate, and approved the revised wording of the Declaration of Independence on July 4."},{id:"m2-q3",context:"The American Revolution",prompt:"Which 1777 American victory convinced France to enter the war openly as a formal military ally of the United States in 1778?",options:["The Saratoga campaign in New York","The Battle of Bunker Hill outside Boston","The Battle of Camden in South Carolina","The Siege of Charleston"],answer:0,entryId:"battles-of-saratoga",explanation:"British General John Burgoyne’s surrender at Saratoga in October 1777 persuaded France to sign the Treaty of Alliance and the Treaty of Amity and Commerce on February 6, 1778, bringing crucial French troops, money, and naval power."},{id:"m2-q4",context:"Siege of Yorktown (1781)",prompt:"Why was British General Lord Cornwallis unable to evacuate or resupply his army by sea during the Siege of Yorktown in October 1781?",options:["A French fleet under Admiral de Grasse defeated the British fleet at the Battle of the Chesapeake and sealed off Chesapeake Bay.","Continental Navy frigates commanded by John Paul Jones blockaded New York Harbor.","A severe hurricane destroyed the entire British transport fleet in Charleston.","Spanish warships closed the mouth of the Hudson River."],answer:0,entryId:"siege-of-yorktown",explanation:"Admiral de Grasse’s victory at the Battle of the Chesapeake trapped Cornwallis on the Yorktown peninsula while Washington’s Continental Army and Rochambeau’s French troops besieged his fortifications by land."},{id:"m2-q5",context:"Independence Hall",prompt:"Which two foundational documents of the United States were debated and signed inside the Assembly Room of the Pennsylvania State House (Independence Hall)?",options:["Both the Declaration of Independence (1776) and the United States Constitution (1787)","The Mayflower Compact (1620) and the Treaty of Paris (1783)","The Federalist Papers (1787) and the Monroe Doctrine (1823)","The Articles of Confederation (1781) and the Emancipation Proclamation (1863)"],answer:0,entryId:"independence-hall",explanation:"Built in the 1730s–1750s as the Pennsylvania State House in Philadelphia, Independence Hall hosted both the Second Continental Congress in 1776 and the Constitutional Convention in 1787."},{id:"m2-q6",context:"Battle of Bunker Hill (1775)",prompt:"Where was the Battle of Bunker Hill actually fought on June 17, 1775?",options:["On Breed’s Hill, the lower hill the militia fortified instead of Bunker Hill","On Bunker Hill itself, after the British dug in on Breed’s Hill","On Dorchester Heights, south of Boston","On Beacon Hill, in the center of Boston"],answer:0,entryId:"battle-of-bunker-hill",explanation:"Colonel William Prescott was ordered to fortify Bunker Hill but chose the lower Breed’s Hill. A British map then reversed the names, and the battle kept the name of its neighbor."},{id:"m2-q7",context:"Valley Forge (1777–78)",prompt:"Who arrived at Valley Forge in February 1778 and drilled the Continental Army into a disciplined force?",options:["Baron Friedrich von Steuben, a former Prussian officer","General Horatio Gates, the victor of Saratoga","Admiral de Grasse of the French navy","General Henry Clinton"],answer:0,entryId:"valley-forge",explanation:"Von Steuben wrote a standard drill (in French, since he spoke no English), formed a model company to demonstrate it, and later turned his methods into the “Blue Book” of army regulations."},{id:"m2-q8",context:"Treaty of Paris (1783)",prompt:"Which river became the western boundary of the United States under the Treaty of Paris of 1783?",options:["The Mississippi River","The Ohio River","The Hudson River","The Missouri River"],answer:0,entryId:"treaty-of-paris-1783",explanation:"Article 2 drew the boundary through the Great Lakes to the Lake of the Woods, then down the Mississippi, and Article 8 kept navigation of the river open to both nations."}]},{id:"revolutionary-founders",shortTitle:"The Founders",number:3,title:"Founders, Diplomats & Revolutionary Voices",years:"1706–1834",subtitle:"Seven lives that shaped the war, the diplomacy, and the arguments of the founding generation",overview:"The Revolution was fought and argued by distinct personalities with competing visions for the new republic: Benjamin Franklin winning French support in Paris, George Washington holding the Continental Army together and setting the precedent of civilian rule, John and Abigail Adams debating law and women’s legal standing, Thomas Jefferson articulating natural rights while holding hundreds in bondage, Alexander Hamilton envisioning an energetic fiscal-military state, and the young Marquis de Lafayette linking the American cause to France.",guidingQuestion:"How did the personal backgrounds and rivalries of the Revolutionary generation shape the character of the early United States?",entryIds:["benjamin-franklin","george-washington","john-adams","abigail-adams","thomas-jefferson","alexander-hamilton","marquis-de-lafayette"],primarySourceChallenge:{id:"psc-founders",quote:"I walk on untrodden ground. There is scarcely any part of my conduct which may not hereafter be drawn into precedent.",speaker:"George Washington",context:"Writing as he began the presidency under the new Constitution",prompt:"Which two voluntary relinquishments of power by George Washington stunned contemporaries and established enduring American precedents?",options:["Resigning his military commission to Congress in December 1783 and retiring after two presidential terms in 1797","Refusing to attend the Constitutional Convention in 1787 and vetoing the Bill of Rights in 1791","Abolishing the cabinet in 1793 and handing command of the army to Thomas Jefferson","Stepping down after one year as president to become Chief Justice of the Supreme Court"],answer:0,entryId:"george-washington",historicalNote:"By surrendering his sword to Congress at Annapolis in 1783 and stepping down after two terms in 1797, Washington cemented civilian supremacy over the military and the peaceful transfer of executive power."},timeline:[{id:"t3-franklin",label:"Benjamin Franklin is born in Boston",date:"1706",sort:1706,entryId:"benjamin-franklin"},{id:"t3-adams",label:"John Adams defends the British soldiers of the Boston Massacre",date:"1770",sort:1770.8,entryId:"john-adams"},{id:"t3-ladies",label:"Abigail Adams urges her husband to “Remember the Ladies”",date:"March 1776",sort:1776.25,entryId:"abigail-adams"},{id:"t3-paris",label:"Franklin, Adams, and John Jay negotiate the peace with Britain",date:"1783",sort:1783.5,entryId:"benjamin-franklin"},{id:"t3-washington",label:"George Washington takes the oath as first president",date:"April 30, 1789",sort:1789.3,entryId:"george-washington"},{id:"t3-adamspres",label:"John Adams wins the presidential election",date:"1796",sort:1796.9,entryId:"john-adams"},{id:"t3-july4",label:"John Adams and Thomas Jefferson die on the same day",date:"July 4, 1826",sort:1826.5,entryId:"thomas-jefferson"}],reflection:{modelAnswer:"The founders brought very different lives to the new nation. Franklin, a self-made printer and scientist, became its great diplomat. Washington, a Virginia planter and soldier, set lasting precedents by twice giving up power. Adams, a blunt New England lawyer, defended unpopular clients and distrusted both kings and mobs, while Abigail Adams pressed for women’s education and legal rights. Jefferson’s ideals of equality sat beside his ownership of hundreds of enslaved people, and Hamilton, an immigrant from the West Indies, built a strong national financial system. Their rivalries, above all between Hamilton and Jefferson and later between Adams and Jefferson, helped create the first political parties and the first peaceful transfer of power between them in 1801.",keyPoints:["Different backgrounds: printer, planter, lawyer, immigrant","Washington’s precedent of giving up power","Contradictions such as slaveholding and ideals of liberty","Women’s voices, such as Abigail Adams","Rivalries that produced the first parties and a peaceful transfer of power"]},deepDive:[{url:"https://www.youtube.com/watch?v=6KK0l_f3lH8",title:"Being a Revolutionary (Yale, The American Revolution, lecture 7, Joanne Freeman)",channel:"YaleCourses",views:96e3,length:"46:05",checked:"2026-10-29"},{url:"https://www.youtube.com/watch?v=fzd06DRvRKA",title:"War and Society (Yale lecture 19)",channel:"YaleCourses",views:59237,length:"43:20",checked:"2026-10-29"},{url:"https://www.youtube.com/watch?v=shTBSGoYtK0",title:"Introduction: Freeman’s Top Five Tips for Studying the Revolution (Yale lecture 1)",channel:"YaleCourses",views:378668,length:"40:23",checked:"2026-10-29"}],quiz:[{id:"m3-q1",context:"Benjamin Franklin",prompt:"Which distinction belongs uniquely to Benjamin Franklin among all the Founders?",options:["He signed the Declaration of Independence (1776), the Treaty of Paris (1783), and the U.S. Constitution (1787).","He served as both the first Secretary of State and the first Chief Justice.","He authored both Common Sense and The Federalist Papers.","He commanded the Continental Navy while serving as governor of Massachusetts."],answer:0,entryId:"benjamin-franklin",explanation:"At eighty-one Franklin was the oldest delegate to the Constitutional Convention, and in Paris he helped win the French alliance and negotiate the peace treaty."},{id:"m3-q2",context:"Abigail Adams",prompt:"What did Abigail Adams urge her husband John Adams to do in her famous March 31, 1776 letter while Congress prepared a new code of laws?",options:["“Remember the Ladies” and limit the unchecked legal power that husbands held over wives under coverture","Establish an hereditary senate modeled on the British House of Lords","Move the national capital permanently to Boston","Appoint George Washington as king of the American states"],answer:0,entryId:"abigail-adams",explanation:"Abigail Adams warned that women would “foment a Rebellion” if the new republic left intact the common-law doctrine of coverture, under which married women had no separate legal identity or property rights."},{id:"m3-q3",context:"John Adams & Thomas Jefferson",prompt:"What extraordinary coincidence occurred on July 4, 1826, the fiftieth anniversary of the Declaration of Independence?",options:["Both John Adams and Thomas Jefferson died within hours of each other on that exact day.","Alexander Hamilton and Aaron Burr fought their duel at Weehawken on that morning.","George Washington delivered his Farewell Address to Congress on that day.","The Constitutional Convention reconvened in Philadelphia to ratify the Bill of Rights."],answer:0,entryId:"john-adams",explanation:"Former rivals and reconciled friends, Jefferson died at Monticello in the early afternoon of July 4, 1826, and Adams died hours later in Quincy, reportedly saying, “Thomas Jefferson survives.”"},{id:"m3-q4",context:"Thomas Jefferson",prompt:"Which three achievements did Thomas Jefferson choose for his own gravestone at Monticello, deliberately omitting his presidency?",options:["Author of the Declaration of Independence, Author of the Virginia Statute for Religious Freedom, and Father of the University of Virginia","President of the United States, Purchaser of Louisiana, and Commander of the Continental Army","Governor of Virginia, Minister to France, and Founder of the Democratic-Republican Party","Author of the Constitution, Signer of the Treaty of Paris, and President of the American Philosophical Society"],answer:0,entryId:"thomas-jefferson",explanation:"Jefferson’s self-written epitaph recorded only those three works as the testimonials by which he wished to be remembered."},{id:"m3-q5",context:"Alexander Hamilton",prompt:"After serving as George Washington’s wartime aide-de-camp and co-authoring The Federalist Papers, what office did Alexander Hamilton hold from 1789 to 1795?",options:["First Secretary of the Treasury, where he established federal credit, assumed state war debts, and chartered a national bank","First Secretary of State, negotiating the Jay Treaty in London","Speaker of the House of Representatives during the First Congress","Governor of New York and commander of the state militia"],answer:0,entryId:"alexander-hamilton",explanation:"Born in Nevis in the British West Indies, Hamilton became the first Treasury secretary and designed the financial architecture of the federal government."},{id:"m3-q6",context:"Marquis de Lafayette",prompt:"What did the Marquis de Lafayette do in France during his leave in 1779 that helped the American cause?",options:["He played a crucial role in securing 6,000 French troops for the war in America.","He persuaded Spain to give Florida to the United States.","He negotiated the Treaty of Paris on behalf of Congress.","He raised a loan from the Dutch Republic to pay the Continental Army."],answer:0,entryId:"marquis-de-lafayette",explanation:"Lafayette, who had sailed to America in 1777 against a royal ban, returned in 1780 with news of French aid, and in 1781 his men held Cornwallis at Yorktown until Washington arrived."}]},{id:"forging-the-constitution",shortTitle:"The Constitution",number:4,title:"From Confederation to Constitution",years:"1777–1788",subtitle:"Postwar crisis, the Philadelphia convention, and the battle over ratification",overview:"Under the Articles of Confederation, the unicameral Congress had no power to levy taxes or regulate interstate commerce. When economic distress and Shays’s Rebellion in western Massachusetts exposed the fragility of the union, fifty-five delegates gathered behind closed doors in Philadelphia from May to September 1787. Led by thinkers like James Madison, they scrapped the Articles, hammered out compromises over representation and slavery, and launched a fierce ratification debate immortalized in The Federalist Papers.",guidingQuestion:"How did the framers of 1787 try to create a national government strong enough to govern without destroying republican liberty?",entryIds:["articles-of-confederation","northwest-ordinance","shays-rebellion","constitutional-convention","constitution","james-madison","federalist-papers","anti-federalists","bill-of-rights"],primarySourceChallenge:{id:"psc-constitution",quote:"Ambition must be made to counteract ambition... If men were angels, no government would be necessary.",speaker:"James Madison (as Publius)",context:"The Federalist No. 51, February 1788",prompt:"How did Madison argue in Federalist No. 10 and No. 51 that the new Constitution would prevent tyranny and majority faction?",options:["By dividing authority across three separate branches with checks and balances and extending the republic across a large, diverse territory so no single faction could easily dominate","By giving the president an absolute veto and life tenure to overrule turbulent state legislatures","By requiring unanimous consent of all thirteen states before any federal law or tax could take effect","By banning political disagreements and requiring all officeholders to belong to a single national party"],answer:0,entryId:"james-madison",historicalNote:"Flipping Montesquieu’s traditional view that republics could survive only in small, homogeneous territories, Madison argued that a large republic with separated powers was the surest safeguard against oppressive majorities."},timeline:[{id:"t4-adopted",label:"Congress adopts the Articles of Confederation",date:"November 15, 1777",sort:1777.9,entryId:"articles-of-confederation"},{id:"t4-force",label:"The Articles take effect after Maryland ratifies",date:"March 1, 1781",sort:1781.2,entryId:"articles-of-confederation"},{id:"t4-annapolis",label:"Delegates from five states meet at Annapolis",date:"September 1786",sort:1786.7,entryId:"shays-rebellion"},{id:"t4-springfield",label:"Shays’s men fail to take the Springfield arsenal",date:"January 1787",sort:1787.05,entryId:"shays-rebellion"},{id:"t4-convention",label:"The Constitutional Convention opens in Philadelphia",date:"May 1787",sort:1787.4,entryId:"constitutional-convention"},{id:"t4-ordinance",label:"Congress adopts the Northwest Ordinance",date:"July 13, 1787",sort:1787.53,entryId:"northwest-ordinance"},{id:"t4-signed",label:"The Constitution is signed",date:"September 17, 1787",sort:1787.71,entryId:"constitution"}],reflection:{modelAnswer:"Under the Articles of Confederation the national government could not tax or regulate trade, and Shays’ Rebellion showed it could not keep order. The framers gave the new government the power to tax and to make laws supreme over the states, but they tried to protect liberty by dividing that power. Authority was split among three branches that check one another, as Madison explained in Federalist No. 51, and between the national government and the states. Compromises such as the two-house Congress balanced large and small states. When critics warned that the plan still lacked protections for individual rights, its supporters promised amendments, which became the Bill of Rights.",keyPoints:["Weaknesses of the Articles: no taxing power, no control of trade","Shays’ Rebellion as a warning","Separation of powers and checks and balances","Federalism: dividing power with the states","The Great Compromise and the Bill of Rights"]},deepDive:[{url:"https://www.youtube.com/watch?v=OVTlyM0-Cc8",title:"Confederation (Yale, The American Revolution, lecture 20, Joanne Freeman)",channel:"YaleCourses",views:58847,length:"43:26",checked:"2026-10-29"},{url:"https://www.youtube.com/watch?v=X3q8xHk7oqk",title:"The Road to a Constitutional Convention (Yale lecture 22)",channel:"YaleCourses",views:58075,length:"44:21",checked:"2026-10-29"},{url:"https://www.youtube.com/watch?v=9PqKRhIKdK8",title:"Creating a Constitution (Yale lecture 23)",channel:"YaleCourses",views:78263,length:"46:00",checked:"2026-10-29"}],quiz:[{id:"m4-q1",context:"Articles of Confederation (1777–1789)",prompt:"What were two major structural weaknesses of the national government under the Articles of Confederation?",options:["Congress could not levy taxes directly or regulate interstate and foreign commerce, and any amendment required unanimous approval of all thirteen states.","The president held unchecked power to dissolve state legislatures and command state militias.","A federal Supreme Court struck down almost every state tax law passed between 1781 and 1787.","Representation in Congress was based strictly on population, allowing Virginia and Massachusetts to outvote all other states."],answer:0,entryId:"articles-of-confederation",explanation:"Under the Articles, each state had one vote in a single-chamber Congress, there was no separate executive or national judiciary, and Congress had to requisition funds from states that often refused to pay."},{id:"m4-q2",context:"The Northwest Ordinance (1787)",prompt:"What lasting policies did the Confederation Congress establish in the Northwest Ordinance of July 1787 for the territory north of the Ohio River?",options:["It created a pathway for new territories to enter the Union as equal states, encouraged public education, and prohibited slavery in the Northwest Territory.","It turned the territory into permanent colonies governed by Virginia and New York without representation in Congress.","It legalized the Atlantic slave trade north of the Ohio River until 1850.","It ceded the entire Great Lakes region back to Great Britain in exchange for trade concessions."],answer:0,entryId:"northwest-ordinance",explanation:"Enacted while the Constitutional Convention was meeting in Philadelphia, the Northwest Ordinance set the precedent that western territories would become co-equal states rather than subordinate colonies and barred slavery north of the Ohio River."},{id:"m4-q3",context:"Shays’s Rebellion (1786–1787)",prompt:"Who led the 1786–1787 armed uprising in western Massachusetts that closed county courts to stop farm foreclosures?",options:["Daniel Shays, a former Continental Army captain, along with indebted farmers and veterans burdened by hard-money state taxes","Ethan Allen and the Green Mountain Boys seeking independence for Vermont","Western Pennsylvania whiskey distillers protesting Alexander Hamilton’s federal excise tax","Loyalist merchants in Boston demanding the return of confiscated Tory estates"],answer:0,entryId:"shays-rebellion",explanation:"When the Confederation Congress proved unable to field troops to assist Massachusetts during Shays’s Rebellion, nationalist leaders like Washington and Madison pointed to the crisis as proof that the Articles had to be replaced."},{id:"m4-q4",context:"The Constitutional Convention (1787)",prompt:"How did the Connecticut (Great) Compromise resolve the deadlock between large states (the Virginia Plan) and small states (the New Jersey Plan)?",options:["It created a bicameral Congress with a House of Representatives apportioned by population and a Senate in which every state received two equal votes.","It allowed every state to have proportional representation in both chambers of Congress.","It gave small states control of the presidency and large states control of the Supreme Court.","It rotated the national capital between New York, Philadelphia, and Virginia every four years."],answer:0,entryId:"constitutional-convention",explanation:"Proposed by Connecticut’s delegates, the compromise broke the convention’s most dangerous impasse over representation."},{id:"m4-q5",context:"The Constitution & The Federalist Papers",prompt:"Who were the three authors who wrote the 85 essays of The Federalist (1787–1788) under the shared Roman pseudonym “Publius”?",options:["Alexander Hamilton, James Madison, and John Jay","Thomas Jefferson, John Adams, and Benjamin Franklin","George Mason, Patrick Henry, and Richard Henry Lee","George Washington, Gouverneur Morris, and Roger Sherman"],answer:0,entryId:"federalist-papers",explanation:"Hamilton organized the project and wrote more than half of the essays, Madison wrote twenty-nine (including Nos. 10 and 51), and Jay wrote the rest, to persuade New Yorkers to ratify the Constitution."},{id:"m4-q6",context:"Anti-Federalists",prompt:"Which omission from the Constitution became the main rallying point for its Anti-Federalist opponents?",options:["It had no bill of rights; the convention had voted down George Mason’s proposal for one.","It did not name a national capital city.","It gave the president no power to command the army.","It created no federal courts at all."],answer:0,entryId:"anti-federalists",explanation:"Anti-Federalists such as Mason, Patrick Henry and “Brutus” warned that a powerful national government without written guarantees would threaten liberty. Several states ratified only while proposing amendments, which led to the Bill of Rights."}]},{id:"ideals-and-contradictions",shortTitle:"Ideals & Contradictions",number:5,title:"Ideas & Contradictions of the Republic",years:"1619–1789",subtitle:"Republicanism, federalism, and the central paradox of American slavery",overview:"The American Revolution was an ideological transformation as well as a political one. Examine the core political concepts that animated the founding, republican self-government rooted in popular sovereignty and the federal division of sovereignty between nation and states, alongside the republic’s deepest contradiction, the persistence and constitutional accommodation of racial slavery.",guidingQuestion:"How could a republic founded on the proposition that “all men are created equal” simultaneously embed protections for human bondage into its fundamental law?",entryIds:["republicanism","federalism","slavery-in-america","african-americans-in-the-revolution","phillis-wheatley"],primarySourceChallenge:{id:"psc-contradictions",quote:"Devise means for removing the Inconsistency from the Character of the American People.",speaker:"Pennsylvania Society for Promoting the Abolition of Slavery (signed by Benjamin Franklin as president)",context:"Petition presented to the First U.S. Congress, February 3, 1790",prompt:"How did the Revolutionary era simultaneously weaken slavery in the North and entrench it in the new federal Constitution?",options:["Northern states began passing gradual emancipation laws or abolishing slavery in court, while the 1787 Constitution included the Three-Fifths Clause, a fugitive-labor clause, and protection for the Atlantic slave trade until at least 1808.","The Constitutional Convention abolished slavery across the Upper South while legalizing it in New England.","The Northwest Ordinance required every new western state to adopt slavery upon admission to the Union.","The Articles of Confederation emancipated all enslaved people who served in the Continental Army and banned cotton cultivation."],answer:0,entryId:"slavery-in-america",historicalNote:"While the Revolutionary era sparked the first wave of gradual emancipation in northern states, Southern delegates at Philadelphia secured constitutional provisions that boosted slave-state representation in Congress and the Electoral College."},timeline:[{id:"t5-somerset",label:"An English court frees James Somerset in the Somerset case",date:"1772",sort:1772.5,entryId:"slavery-in-america"},{id:"t5-dunmore",label:"Lord Dunmore offers freedom to enslaved people who join the British",date:"1775",sort:1775.9,entryId:"american-revolution"},{id:"t5-declaration",label:"The Declaration proclaims that “all men are created equal”",date:"1776",sort:1776.5,entryId:"declaration-of-independence"},{id:"t5-ordinance",label:"The Northwest Ordinance bans slavery north of the Ohio",date:"1787",sort:1787.5,entryId:"northwest-ordinance"},{id:"t5-petition",label:"Franklin signs an abolitionist petition to the First Congress",date:"February 3, 1790",sort:1790.1,entryId:"benjamin-franklin"},{id:"t5-1808",label:"Congress bans the import of enslaved people",date:"January 1, 1808",sort:1808,entryId:"slavery-in-america"}],reflection:{modelAnswer:"The Revolution’s ideals were universal, but the men who wrote them included enslavers, and the union needed the slaveholding states. Congress cut Jefferson’s passage against the slave trade from the Declaration, and in 1787 the framers compromised: the Constitution never used the word “slavery,” yet it counted three-fifths of enslaved people for representation, protected the slave trade until 1808, and required that people who escaped be returned. At the same time, the Revolution’s language of liberty inspired northern states to begin ending slavery, the Northwest Ordinance kept it out of a vast territory, and Black Americans and abolitionists used the Declaration’s own words to demand freedom. The contradiction was built into the founding and was resolved only by the Civil War.",keyPoints:["Universal ideals written by enslavers","Political need to keep the slaveholding states in the union","Constitutional protections: three-fifths, 1808, fugitive clause","Antislavery steps: northern emancipation, the Northwest Ordinance","Black Americans and abolitionists turning the founders’ words against slavery"]},deepDive:[{url:"https://www.youtube.com/watch?v=RtlB13DleLk",title:"Being an American: The Legacy of the Revolution (Yale, The American Revolution, lecture 25, Joanne Freeman)",channel:"YaleCourses",views:51047,length:"41:19",checked:"2026-10-29"},{url:"https://www.youtube.com/watch?v=3Bo9E-20ApU",title:"Creating a Nation (Yale lecture 24)",channel:"YaleCourses",views:58e3,length:"40:56",checked:"2026-10-29"},{url:"https://www.youtube.com/watch?v=vMR6f7bxHzo",title:"America at 250, Class 2: Revolutionary (and Not So Revolutionary) Beginnings (Yale DeVane Lecture)",channel:"YaleCourses",views:31812,length:"41:13",checked:"2026-10-29"}],quiz:[{id:"m5-q1",context:"Republicanism",prompt:"In Revolutionary political thought, what did “republicanism” hold to be the foundation of legitimate government?",options:["Popular sovereignty: government without a hereditary monarch or aristocracy, resting on the consent and civic virtue of the people","Rule by an enlightened monarch advised by an appointed council of colonial governors","Direct democracy in which all national laws are voted on weekly in town meetings without representatives","Complete abolition of private property and state governments in favor of a single unitary parliament"],answer:0,entryId:"republicanism",explanation:"Drawing on classical antiquity, English commonwealth writers, and the Enlightenment, American republicanism rejected hereditary rule and emphasized representative self-government and vigilance against corruption."},{id:"m5-q2",context:"Federalism",prompt:"What defines “federalism” in the American constitutional system?",options:["The division and sharing of governing power between a national government of enumerated powers and state governments","A system in which state governments are mere administrative districts that can be abolished by Congress at will","A loose league of states in which the central government cannot act directly on individual citizens","The rule that only members of the Federalist Party may serve on the Supreme Court"],answer:0,entryId:"federalism",explanation:"Unlike a unitary state or a loose confederation, the Constitution created a compound republic in which both the federal government and the states derive authority from the people and act directly on citizens."},{id:"m5-q3",context:"Slavery in America & The Constitution",prompt:"How did the Three-Fifths Compromise in the 1787 Constitution affect political power in the early republic?",options:["It counted three-fifths of the enslaved population toward a state’s representation in the House of Representatives and the Electoral College, giving slaveholding states extra political weight.","It granted three-fifths of enslaved people the right to vote in federal elections.","It required three-fifths of all federal tax revenue to be spent compensating emancipated people.","It allowed Congress to ban slavery whenever three-fifths of the Senate voted to do so."],answer:0,entryId:"constitutional-convention",explanation:"Without ever using the words “slave” or “slavery,” the Constitution counted three-fifths of “all other Persons” for apportionment, increasing Southern seats in the House and electoral votes for president."},{id:"m5-q4",context:"Slavery in the Revolutionary War",prompt:"Roughly how many Black Americans served in the Continental Army and Navy, and how many sought freedom with the British following proclamations like Lord Dunmore’s?",options:["An estimated 5,000–6,000 fought for American independence, while about 20,000 joined or fled to the British lines seeking freedom.","Black Americans were completely barred from both armies throughout the entire eight-year war.","Over 100,000 fought in the Continental Army and none joined the British.","Only enslaved people in Canada participated in the war."],answer:0,entryId:"american-revolution",explanation:"African Americans weighed which side offered the best chance at freedom: thousands served in Continental regiments and at sea, while roughly 20,000 sought liberty behind British lines."},{id:"m5-q5",context:"African Americans in the Revolution",prompt:"What did Lord Dunmore, the royal governor of Virginia, offer in his proclamation of 1775?",options:["Freedom to enslaved people and indentured servants of rebels who left them to join the British","Land in Canada to any colonist who stayed loyal to the king","An end to the Atlantic slave trade in all British colonies","A pardon for every Patriot who laid down his arms"],answer:0,entryId:"african-americans-in-the-revolution",explanation:"The American Yawp calls Dunmore’s offer the first mass emancipation in American history, though British motives were practical rather than humanitarian. About 500 to 1,000 men joined his “Ethiopian Regiment.”"},{id:"m5-q6",context:"Phillis Wheatley",prompt:"Why did Phillis Wheatley’s 1773 book of poems open with a statement signed by John Hancock and other Boston notables?",options:["To prove to doubtful readers that an enslaved African woman had really written the poems","Because the poems criticized the Boston Tea Party","Because Hancock had paid for her to sail to London","To announce that the Massachusetts legislature had freed her"],answer:0,entryId:"phillis-wheatley",explanation:"Many white readers did not believe a Black woman could write poetry. The statement and her portrait at a writing desk were meant to prove the book was hers. It made her the first African American to publish a book of poetry."}]}],finalExam:[{id:"final-1",context:"Module 1 · Pre-Colonial & Colonial Roots",prompt:"The Haudenosaunee Confederacy expanded from Five Nations to Six Nations when which people joined the league?",options:["The Tuscarora","The Cherokee","The Shawnee","The Delaware (Lenape)"],answer:0,entryId:"haudenosaunee-confederacy",explanation:"The Tuscarora joined after the founding as the sixth nation. In the Grand Council they have no vote of their own and speak through the Cayuga."},{id:"final-2",context:"Module 1 · Imperial Crisis",prompt:"What treaty ended the French and Indian War (Seven Years’ War) in 1763, transferring French Canada and territory east of the Mississippi to Great Britain?",options:["The Treaty of Paris of 1763","The Treaty of Ghent","The Treaty of Guadalupe Hidalgo","The Jay Treaty"],answer:0,entryId:"french-and-indian-war",explanation:"The 1763 Treaty of Paris ended French imperial rule on the North American mainland east of the Mississippi River, setting the stage for Britain’s postwar taxation of the colonies."},{id:"final-3",context:"Module 1 · Stamp Act Crisis",prompt:"In October 1765, delegates from nine colonies met in New York at the Stamp Act Congress and asserted what core constitutional principle?",options:["That colonists could be taxed only by their own elected representative assemblies, not by a Parliament in which they had no representatives","That the thirteen colonies were already an independent republic allied with France","That only the King personally, and never any legislature, could levy taxes","That all customs duties on sugar and molasses were welcome so long as paper remained untaxed"],answer:0,entryId:"stamp-act-crisis",explanation:"The Stamp Act Congress’s Declaration of Rights and Grievances articulated the colonial constitutional position of “no taxation without representation.”"},{id:"final-4",context:"Module 1 · The Boston Massacre",prompt:"What was the outcome of the fall 1770 Boston trials of Captain Thomas Preston and the eight British soldiers of the 29th Regiment of Foot?",options:["Preston and six soldiers were acquitted, while two soldiers were convicted of manslaughter and branded on the hand.","All nine British soldiers were hanged on Boston Common.","Governor Hutchinson pardoned all nine men before a jury could hear the case.","The soldiers were shipped to London and promoted by King George III."],answer:0,entryId:"boston-massacre",explanation:"Defended by John Adams and Josiah Quincy Jr., Preston and six soldiers were acquitted; Hugh Montgomery and Matthew Kilroy were convicted of manslaughter, claimed benefit of clergy, and were branded on the hand instead of being hanged."},{id:"final-5",context:"Module 1 · First Continental Congress",prompt:"Which was the only one of the thirteen colonies that did not send delegates to the First Continental Congress in Philadelphia in September 1774?",options:["Georgia","Rhode Island","Virginia","New York"],answer:0,entryId:"continental-congress",explanation:"Twelve colonies attended the First Continental Congress in 1774 (Georgia, facing frontier conflict and needing British military support, did not send delegates until the Second Continental Congress in 1775). By contrast, Rhode Island was the state absent from the 1787 Constitutional Convention."},{id:"final-6",context:"Module 2 · War for Independence",prompt:"In January 1776, whose bestselling pamphlet *Common Sense* declared that “there is something absurd, in supposing a continent to be perpetually governed by an island”?",options:["Thomas Paine","Thomas Jefferson","Samuel Adams","Alexander Hamilton"],answer:0,entryId:"american-revolution",explanation:"Thomas Paine’s *Common Sense* (January 1776) attacked hereditary monarchy directly in plain, fiery language and shifted public opinion rapidly toward complete independence."},{id:"final-7",context:"Module 2 · The Declaration of Independence",prompt:"Who were the five members appointed by Congress on June 11, 1776, to the “Committee of Five” charged with drafting the Declaration of Independence?",options:["Thomas Jefferson, John Adams, Benjamin Franklin, Roger Sherman, and Robert R. Livingston","George Washington, James Madison, Alexander Hamilton, Patrick Henry, and John Jay","Samuel Adams, John Hancock, Richard Henry Lee, George Mason, and Caesar Rodney","Thomas Paine, Benjamin Rush, Gouverneur Morris, James Wilson, and John Dickinson"],answer:0,entryId:"declaration-of-independence",explanation:"The Committee of Five assigned the initial drafting to Thomas Jefferson, with Adams and Franklin making minor edits before submitting the text to Congress on June 28, 1776."},{id:"final-8",context:"Module 2 · Siege of Yorktown & Peace",prompt:"Although Lord Cornwallis surrendered at Yorktown in October 1781, what 1783 agreement formally ended the Revolutionary War and recognized U.S. independence to the Mississippi River?",options:["The Treaty of Paris, signed September 3, 1783, negotiated by Benjamin Franklin, John Adams, and John Jay","The Articles of Confederation, signed at Yorktown in 1781","The Olive Branch Petition, signed in London in 1782","The Treaty of Alliance with Spain, signed in Madrid in 1783"],answer:0,entryId:"american-revolution",explanation:"Signed on September 3, 1783, the Treaty of Paris recognized the United States as sovereign and established boundaries stretching to the Mississippi River."},{id:"final-9",context:"Module 3 · George Washington",prompt:"What provisions did George Washington make in his 1799 will regarding the enslaved people at Mount Vernon?",options:["He ordered the emancipation of the enslaved people he held in his own right, to take effect after Martha Washington’s death.","He sold the entire Mount Vernon estate and made no provision for emancipation.","He could legally free all the “dower” enslaved people owned by the Custis estate without compensation.","He freed all enslaved people at Mount Vernon in 1776 upon taking command of the Continental Army."],answer:0,entryId:"george-washington",explanation:"Washington, who held hundreds of people in slavery over his life, arranged in his will to free the people he owned outright, but only after his wife’s death."},{id:"final-10",context:"Module 4 · The Constitutional Convention",prompt:"Which state refused to send any delegates to the 1787 Constitutional Convention in Philadelphia and was the last of the thirteen states to ratify the Constitution, in 1790?",options:["Rhode Island","Georgia","Delaware","New Hampshire"],answer:0,entryId:"constitutional-convention",explanation:"Rhode Island’s country-party legislature, protective of its paper-money policy and state autonomy, boycotted the 1787 Philadelphia convention."},{id:"final-11",context:"Module 4 · Dissenters at Philadelphia",prompt:"Which three delegates remained at the Constitutional Convention until September 17, 1787, but refused to sign the finished Constitution, citing among their objections the absence of a Bill of Rights?",options:["George Mason and Edmund Randolph of Virginia, and Elbridge Gerry of Massachusetts","Alexander Hamilton of New York, Benjamin Franklin of Pennsylvania, and John Dickinson of Delaware","Thomas Jefferson of Virginia, John Adams of Massachusetts, and Patrick Henry of Virginia","Roger Sherman of Connecticut, William Paterson of New Jersey, and Luther Martin of Maryland"],answer:0,entryId:"constitutional-convention",explanation:"Thirty-nine delegates signed on September 17, 1787; Mason, Randolph, and Gerry refused, helping spark the ratification debate that led to the Bill of Rights in 1791."},{id:"final-12",context:"Module 4 · Ratification of the Constitution",prompt:"How many of the thirteen states had to ratify the Constitution under Article VII for the new government to take effect, and which state became the decisive ninth ratifier in June 1788?",options:["Nine states; New Hampshire became the ninth in the summer of 1788","All thirteen states unanimously; Virginia was the thirteenth in 1788","Seven states; Delaware was the seventh in December 1787","Ten states; New York was the tenth in July 1788"],answer:0,entryId:"constitution",explanation:"Bypassing the Articles of Confederation’s unanimity rule, Article VII required nine state ratifying conventions; New Hampshire was ninth in the summer of 1788, and Virginia and New York soon followed."},{id:"final-13",context:"Module 4 · James Madison & The Federalist",prompt:"In *The Federalist* No. 10, what did James Madison argue was the most common and durable source of political “factions”?",options:["The “various and unequal distribution of property” and competing economic interests in a free society","Foreign interference by European ambassadors in state elections","Differences in language between New England and the Southern states","Disagreements over the design of the national flag and coinage"],answer:0,entryId:"james-madison",explanation:"Madison argued in Federalist No. 10 that the causes of faction are sown in human nature, especially the unequal distribution of property, and that a republic must control faction’s effects rather than destroy liberty."},{id:"final-14",context:"Module 5 · Ideas & Contradictions",prompt:"Alongside the Three-Fifths Clause, what restriction did Article I, Section 9 of the Constitution place on Congress regarding the transatlantic slave trade?",options:["It barred Congress from prohibiting the “Migration or Importation” of enslaved people prior to the year 1808.","It permanently guaranteed the transatlantic slave trade against any future constitutional amendment.","It immediately outlawed the importation of enslaved people into all thirteen states in 1787.","It gave state governors exclusive authority to regulate foreign trade forever."],answer:0,entryId:"constitutional-convention",explanation:"To keep South Carolina and Georgia in the Union, the convention agreed that Congress could not ban the external slave trade before 1808 (which Congress then outlawed effective January 1, 1808)."},{id:"final-15",context:"Synthesis · 1763–1789",prompt:"Why did Anti-Federalist critics like Patrick Henry and George Mason initially oppose ratification of the 1787 Constitution, and what major concession resulted from their campaign?",options:["They feared the new central government would swallow state authority and individual liberties because it lacked an explicit declaration of rights. This led Madison to shepherd the Bill of Rights through the First Congress.","They demanded that the United States return to British rule under a constitutional monarchy.","They wanted to abolish all state governments and replace them with a single unitary parliament.","They opposed the Northwest Ordinance’s ban on noble titles."],answer:0,entryId:"constitution",explanation:"Anti-Federalist opposition in key states like Massachusetts, Virginia, and New York secured ratification recommendations that prompted James Madison to introduce the amendments ratified in 1791 as the Bill of Rights."}]},{id:"early-republic",periodId:"early-republic",title:"The Early Republic",subtitle:"From Washington’s Inauguration to the Age of Jackson",years:"1789–1828",estimatedHours:"5–7 hours",heroImage:"/images/louisiana-purchase.jpg",heroAlt:"Map of the Louisiana Purchase within the present-day United States",deepDiveNote:"Longer lectures and documentaries for viewers who want more depth.",summary:"Follow the first generation under the Constitution as Americans invented a working government, divided into parties and peacefully handed power to their rivals, doubled the nation’s size, fought Britain again, and built canals and markets, while slavery spread west and Native nations fought for their lands.",modules:[{id:"government-invented",shortTitle:"A Government Invented",number:1,title:"A Government Invented",years:"1789–1801",subtitle:"The presidency, Congress, the courts and the first parties take shape",overview:"The Constitution was a blueprint, not a working government. In the 1790s Americans filled it in: Washington set precedents for the presidency, Congress organized itself and its power of the purse, the Judiciary Act created the federal courts, and quarrels between Hamilton and Jefferson produced the first political parties. The decade ended with a bitter election that tested whether power could pass peacefully from one party to another.",guidingQuestion:"How did Americans turn the Constitution’s outline into a working government in its first decade?",entryIds:["presidency","congress","supreme-court","political-parties","thanksgiving","white-house","election-of-1800"],primarySourceChallenge:{id:"psc-government-invented",quote:"Let me now take a more comprehensive view, and warn you in the most solemn manner against the baneful effects of the spirit of party generally.",speaker:"George Washington",context:"Farewell Address, published September 1796",prompt:"What does Washington’s warning reveal about American politics at the end of his presidency?",options:["Parties had already formed around Hamilton and Jefferson, and Washington feared they would divide the republic.","The Constitution required presidents to belong to no party, and Washington was reminding Congress of that rule.","Washington was urging Americans to join the Federalist Party before the election of 1796.","Political parties were not yet imagined, and Washington was warning against a distant possibility."],answer:0,entryId:"political-parties",historicalNote:"The Constitution made no provision for parties, but divisions between Hamilton’s Federalists and Jefferson’s Democratic-Republicans had formed inside Washington’s own administration. Within four years the election of 1800 would be fought between them."},timeline:[{id:"t1-inaug",label:"Washington takes the oath as the first president",date:"April 30, 1789",sort:1789.33,entryId:"presidency"},{id:"t1-thanks",label:"Washington proclaims the first national Thanksgiving under the Constitution",date:"November 26, 1789",sort:1789.9,entryId:"thanksgiving"},{id:"t1-court",label:"The Supreme Court first assembles in New York City",date:"February 1790",sort:1790.1,entryId:"supreme-court"},{id:"t1-cornerstone",label:"The cornerstone of the President’s House is laid",date:"October 13, 1792",sort:1792.8,entryId:"white-house"},{id:"t1-farewell",label:"Washington warns against “the spirit of party” in his Farewell Address",date:"September 1796",sort:1796.7,entryId:"political-parties"},{id:"t1-adams",label:"John and Abigail Adams move into the President’s House",date:"November 1800",sort:1800.85,entryId:"white-house"},{id:"t1-1800",label:"The House chooses Jefferson on the thirty-sixth ballot",date:"February 1801",sort:1801.1,entryId:"election-of-1800"}],reflection:{modelAnswer:"Much of the working government was invented by practice. Washington, aware that his conduct would become precedent, created the cabinet and stepped down after two terms. Congress used its power of the purse, with revenue bills starting in the House. The Judiciary Act of 1789 built the federal courts that Article III had only sketched. Disputes over Hamilton’s debt and bank plans split the government into Federalists and Democratic-Republicans, parties the Constitution never mentioned. The election of 1800 exposed a flaw in the electoral rules, but Adams left office peacefully, and the Twelfth Amendment adapted the Constitution to party politics.",keyPoints:["Washington’s precedents: the cabinet and the two-term tradition","Congress and the power of the purse","The Judiciary Act of 1789 and the early Supreme Court","The rise of parties the Constitution did not foresee","The peaceful transfer of power in 1800 and the Twelfth Amendment"]},deepDive:[{url:"https://www.youtube.com/watch?v=jMJLuErzYtg",title:"America at 250, Class 7: What Kind of Nation? Democracy, Hamilton, Jefferson, & More",channel:"YaleCourses",views:14365,length:"51:57",checked:t},{url:"https://www.youtube.com/watch?v=Zt4lmLK_OUc",title:"Thomas Jefferson vs Alexander Hamilton (APUSH Review)",channel:"Tom Richey",views:352629,length:"10:33",checked:t},{url:"https://www.youtube.com/watch?v=MdL47Bi-G2A",title:"History of the White House",channel:"C-SPAN's American History TV",views:245155,length:"1:47:42",checked:t}],quiz:[{id:"er1-q1",context:"The Presidency",prompt:"Which precedent did George Washington set that lasted until Franklin Roosevelt and was later written into the Twenty-second Amendment?",options:["Retiring after two terms","Refusing to veto any bill passed by Congress","Choosing his own vice president","Delivering the State of the Union in person every month"],answer:0,entryId:"presidency",explanation:"Every president until Franklin Roosevelt followed Washington’s example of retiring after two terms; the Twenty-second Amendment, ratified in 1951, made the limit law. Every president has also worked with a cabinet, another of Washington’s creations."},{id:"er1-q2",context:"Congress",prompt:"What was the Great Compromise of 1787?",options:["A House of Representatives apportioned by population and a Senate with two members from every state","An agreement to count enslaved people as five-sixths of a free person","A plan for the president to be chosen by Congress","A promise to add a bill of rights after ratification"],answer:0,entryId:"congress",explanation:"The large and small states argued for weeks over representation. Benjamin Franklin compared the solution to a carpenter’s “good joint”: the House gives seats by population and the Senate gives each state two."},{id:"er1-q3",context:"The Supreme Court",prompt:"How many justices did the Judiciary Act of 1789 give the Supreme Court?",options:["Six: a Chief Justice and five associate justices","Nine, the same number as today","Three, one for each circuit","Thirteen, one for each state"],answer:0,entryId:"supreme-court",explanation:"The act created thirteen judicial districts, three circuits and a Court of six justices. The number changed six times before settling at nine in 1869."},{id:"er1-q4",context:"The White House",prompt:"Who built the President’s House between 1792 and 1800?",options:["Free white workers alongside enslaved people hired out by their owners","Only British stonemasons brought over by the architect","Soldiers of the Continental Army","Volunteers from every state in the Union"],answer:0,entryId:"white-house",explanation:"The commissioners hired enslaved people “by the year,” paying their owners. Over 200 enslaved workers have been identified on the White House and the Capitol, including four carpenters owned by the architect James Hoban."},{id:"er1-q5",context:"The Election of 1800",prompt:"Why did the House of Representatives have to decide the election of 1800?",options:["Jefferson and his own running mate, Aaron Burr, tied with 73 electoral votes each","John Adams refused to accept the result","No candidate appeared on the ballot in New York","The Senate had declared the election invalid"],answer:0,entryId:"election-of-1800",explanation:"Under the original rules electors cast two votes without naming which was for president. Every Republican elector voted for both Jefferson and Burr, producing a tie that the Federalist-controlled House broke on the thirty-sixth ballot."}]},{id:"jeffersons-republic",shortTitle:"Jefferson’s Republic",number:2,title:"Jefferson’s Republic and the West",years:"1801–1811",subtitle:"Judicial review, the Louisiana Purchase, and the peoples of the West",overview:"Jefferson called his election “the revolution of 1800,” yet his years in office brought some of the boldest uses of national power in the early republic. Chief Justice John Marshall claimed for the courts the power of judicial review. The Louisiana Purchase doubled the country, and Lewis and Clark crossed the continent with the help of Native hosts such as Sacagawea. In the Old Northwest, Tecumseh and his brother built a confederacy to stop American expansion.",guidingQuestion:"How did the Jefferson years expand national power and the nation’s territory, and what did that mean for Native peoples?",entryIds:["marbury-v-madison","john-marshall","louisiana-purchase","lewis-and-clark-expedition","sacagawea","tecumseh"],primarySourceChallenge:{id:"psc-jeffersons-republic",quote:"A woman with a party of men is a token of peace.",speaker:"William Clark",context:"Expedition journal, 1805, writing about Sacagawea",prompt:"What does Clark’s remark reveal about Sacagawea’s role in the Lewis and Clark Expedition?",options:["Her presence showed the nations they met that the party was not a war party.","She was the expedition’s commander, chosen by Jefferson.","She guided the Corps from St. Louis to the Pacific without help.","She was hired to negotiate the Louisiana Purchase with France."],answer:0,entryId:"sacagawea",historicalNote:"The National Park Service says the journals offer little evidence that Sacagawea guided the whole journey. Her importance lay elsewhere: her presence reassured the tribes they met, and in her Shoshone homeland she helped the Corps find the horses it needed to cross the mountains."},timeline:[{id:"t2-secret",label:"Jefferson secretly asks Congress for $2,500 to explore the West",date:"January 18, 1803",sort:1803.05,entryId:"lewis-and-clark-expedition"},{id:"t2-marbury",label:"The Supreme Court decides Marbury v. Madison",date:"February 1803",sort:1803.15,entryId:"marbury-v-madison"},{id:"t2-purchase",label:"The Louisiana Purchase treaty is signed in Paris",date:"April 30, 1803",sort:1803.33,entryId:"louisiana-purchase"},{id:"t2-depart",label:"The Corps of Discovery starts up the Missouri River",date:"May 14, 1804",sort:1804.37,entryId:"lewis-and-clark-expedition"},{id:"t2-ocean",label:"Clark writes “Ocian in view! O! the joy”",date:"November 7, 1805",sort:1805.85,entryId:"lewis-and-clark-expedition"},{id:"t2-return",label:"The Corps returns to St. Louis",date:"September 23, 1806",sort:1806.73,entryId:"lewis-and-clark-expedition"},{id:"t2-tippecanoe",label:"Harrison’s troops defeat Tenskwatawa at Tippecanoe",date:"November 7, 1811",sort:1811.85,entryId:"tecumseh"}],reflection:{modelAnswer:"The Jefferson years expanded national power in ways Jefferson’s own philosophy resisted. In Marbury v. Madison, Marshall’s Court declared an act of Congress unconstitutional and claimed the power of judicial review. Jefferson, despite doubts about whether the Constitution allowed it, bought Louisiana from France for $15 million, doubling the country, and sent Lewis and Clark across the continent. The expedition depended on more than fifty Native nations and on Sacagawea. For those nations, the new territory meant traders, settlers and treaties that would take their land, which is why Tecumseh and Tenskwatawa tried to unite them in resistance.",keyPoints:["Judicial review in Marbury v. Madison","The Louisiana Purchase and its constitutional doubts","Lewis and Clark’s dependence on Native help","Tecumseh’s confederacy as a response to expansion"]},deepDive:[{url:"https://www.youtube.com/watch?v=MNxmboWs0H8",title:"America’s Louisiana Purchase: Noble Bargain, Difficult Journey",channel:"Louisiana Public Broadcasting",views:39829,length:"27:21",checked:t},{url:"https://www.youtube.com/watch?v=reLDLnUfc_0",title:"Marbury v Madison: the most important case in US Supreme Court history",channel:"Jeffrey Kaplan",views:63860,length:"21:42",checked:t},{url:"https://www.youtube.com/watch?v=cH-T2aY4DPY",title:"Tecumseh and the Native American Resistance",channel:"Kings and Generals",views:2040247,length:"58:03",checked:t}],quiz:[{id:"er2-q1",context:"Marbury v. Madison (1803)",prompt:"What did the Supreme Court do for the first time in Marbury v. Madison?",options:["Declared an act of Congress unconstitutional","Removed a president from office","Ruled that states could tax the national bank","Ordered James Madison to deliver William Marbury’s commission"],answer:0,entryId:"marbury-v-madison",explanation:"Marshall held that Marbury had a right to his commission but that the Court could not order it delivered, because part of the Judiciary Act of 1789 conflicted with the Constitution. “A law repugnant to the Constitution is void.”"},{id:"er2-q2",context:"The Louisiana Purchase",prompt:"What had Jefferson originally instructed his diplomats to buy from France?",options:["New Orleans and the Floridas, for up to $10 million","The whole Louisiana Territory, for $15 million","Canada, in exchange for American support against Britain","Only the right to ship goods through New Orleans"],answer:0,entryId:"louisiana-purchase",explanation:"Napoleon, who had lost an army in Haiti and expected war with Britain, offered the entire territory instead. The treaty, signed on April 30, 1803, doubled the size of the United States."},{id:"er2-q3",context:"The Lewis and Clark Expedition",prompt:"When Clark wrote “Ocian in view! O! the joy” on November 7, 1805, what was he actually looking at?",options:["The estuary of the Columbia River, still short of the Pacific","The Gulf of Mexico","Lake Superior","The Pacific Ocean from the summit of the Rockies"],answer:0,entryId:"lewis-and-clark-expedition",explanation:"The National Park Service notes that it would be another couple of weeks before Lewis and Clark stood at the Pacific itself. They wintered at Fort Clatsop on the coast."},{id:"er2-q4",context:"Sacagawea",prompt:"Why do the spellings Sacagawea, Sacajawea and Sakakawea all exist?",options:["The journals spell her name eight ways, an 1814 editor changed the “g” to a “j,” and North Dakota built its own spelling from Hidatsa words","She changed her name three times during the expedition","Each spelling comes from a different treaty she signed","Congress adopted all three in an act of 1806"],answer:0,entryId:"sacagawea",explanation:"Nicholas Biddle’s 1814 edition introduced “Sacajawea” for no known reason; some Shoshone hold it is a Shoshone name meaning “boat launcher.” “Sakakawea” combines Hidatsa words for “bird” and “woman.”"},{id:"er2-q5",context:"Tecumseh",prompt:"What happened at Prophetstown in November 1811 while Tecumseh was away in the South?",options:["Tenskwatawa attacked Harrison’s army against Tecumseh’s warnings, lost, and Harrison burned the town","Tecumseh’s confederacy signed a peace treaty with the United States","British troops arrived to defend the town","The Creek Nation joined the confederacy in a grand council"],answer:0,entryId:"tecumseh",explanation:"Tecumseh returned three months later to find Prophetstown in ruins. The defeat at Tippecanoe pushed him into an alliance with Britain in the War of 1812."}]},{id:"war-and-nation",shortTitle:"War & Nation",number:3,title:"A Second War and a Stronger Nation",years:"1812–1823",subtitle:"The War of 1812, national power, and the first great crisis over slavery",overview:"War with Britain in 1812 brought failed invasions of Canada, the burning of Washington, and a peace that restored the prewar boundaries. Americans still emerged confident: the Supreme Court upheld broad national power in McCulloch v. Maryland, and the Monroe Doctrine warned Europe away from the Americas. But when Missouri asked to enter the Union as a slave state, the country met its first great sectional crisis, and the aging Jefferson heard “a fire bell in the night.”",guidingQuestion:"How did the War of 1812 and its aftermath strengthen the nation, and why did the Missouri crisis alarm Americans?",entryIds:["war-of-1812","mcculloch-v-maryland","monroe-doctrine","missouri-compromise"],primarySourceChallenge:{id:"psc-war-and-nation",quote:"This momentous question, like a fire bell in the night, awakened and filled me with terror. I considered it at once as the knell of the Union.",speaker:"Thomas Jefferson",context:"Letter to John Holmes, April 22, 1820",prompt:"What “momentous question” alarmed Jefferson in 1820?",options:["Whether slavery would be allowed to spread into new western states such as Missouri","Whether the United States should go to war again with Britain","Whether the Supreme Court could strike down acts of Congress","Whether the national capital should move back to Philadelphia"],answer:0,entryId:"missouri-compromise",historicalNote:"The Missouri crisis split the Democratic-Republican Party along sectional lines. Jefferson warned that a line dividing slave and free states, once drawn, would never be erased and that every new irritation “will mark it deeper and deeper.”"},timeline:[{id:"t3-declare",label:"Congress declares war on Britain",date:"June 18, 1812",sort:1812.46,entryId:"war-of-1812"},{id:"t3-thames",label:"Tecumseh is killed at the Battle of the Thames",date:"October 5, 1813",sort:1813.76,entryId:"war-of-1812"},{id:"t3-burn",label:"British troops burn Washington, D.C.",date:"August 24, 1814",sort:1814.65,entryId:"war-of-1812"},{id:"t3-ghent",label:"The Treaty of Ghent is signed",date:"December 24, 1814",sort:1814.98,entryId:"war-of-1812"},{id:"t3-orleans",label:"Jackson defeats the British at New Orleans",date:"January 8, 1815",sort:1815.02,entryId:"war-of-1812"},{id:"t3-mcculloch",label:"The Supreme Court decides McCulloch v. Maryland",date:"March 6, 1819",sort:1819.18,entryId:"mcculloch-v-maryland"},{id:"t3-missouri",label:"Conference committee reports the Missouri Compromise",date:"March 1, 1820",sort:1820.17,entryId:"missouri-compromise"},{id:"t3-monroe",label:"Monroe announces the Monroe Doctrine",date:"December 2, 1823",sort:1823.92,entryId:"monroe-doctrine"}],reflection:{modelAnswer:"The War of 1812 ended in a draw on paper, with the Treaty of Ghent restoring prewar boundaries, but Americans came out of it confident. Jackson’s victory at New Orleans gave them a hero, the Federalist Party that had opposed the war collapsed, and the Supreme Court in McCulloch v. Maryland upheld broad national power and barred states from taxing federal institutions. In 1823 the Monroe Doctrine claimed the hemisphere as off-limits to new European colonies, though the country lacked the power to enforce it. The Missouri crisis exposed the weakness beneath this confidence: northern and southern congressmen voted along sectional lines over slavery’s expansion, the governing party split, and the 36°30′ line only postponed the conflict.",keyPoints:["The Treaty of Ghent and postwar nationalism","The defeat of Native nations in the war","McCulloch v. Maryland and implied powers","The Monroe Doctrine as an aspiration","The Missouri crisis and sectional division"]},deepDive:[{url:"https://www.youtube.com/watch?v=Tq0LLB-X4is",title:"The War of 1812",channel:"Buffalo Toronto Public Media",views:0xb086db,length:"1:53:17",checked:t},{url:"https://www.youtube.com/watch?v=PBLkMoqyoQU",title:"What Caused the War of 1812? (Documentary)",channel:"Real Time History",views:727710,length:"27:13",checked:t},{url:"https://www.youtube.com/watch?v=d9hQk2Mmpcw",title:"Slavery and Missouri Compromise in early 1800s",channel:"Khan Academy",views:187383,length:"11:00",checked:t}],quiz:[{id:"er3-q1",context:"The War of 1812",prompt:"What did the Treaty of Ghent provide?",options:["A return to prewar boundaries, a boundary commission and peace with Native nations","The surrender of Canada to the United States","A British promise to end impressment forever","Recognition of a Native nation in the Old Northwest"],answer:0,entryId:"war-of-1812",explanation:"The terms were status quo ante bellum. The treaty said nothing about impressment, and Britain dropped the Native nations’ hope for a recognized homeland, which made them, in the Battlefield Trust’s words, “the worst losers of the war.”"},{id:"er3-q2",context:"The War of 1812",prompt:"Why was the Battle of New Orleans fought after the peace treaty had been signed?",options:["News of the treaty had not yet crossed the Atlantic, and it took effect only on ratification","Jackson ignored a direct order from Madison to stop fighting","The British refused to accept the treaty in Louisiana","Congress had voted to continue the war"],answer:0,entryId:"war-of-1812",explanation:"The treaty was signed on December 24, 1814; the battle was fought on January 8, 1815. Sources disagree on whether it was “ultimately pointless” or, since the treaty required ratification, justified."},{id:"er3-q3",context:"McCulloch v. Maryland (1819)",prompt:"Why, according to Marshall, could Maryland not tax the Second Bank of the United States?",options:["“The power to tax involves the power to destroy,” and states cannot control the federal government","The bank had already paid its taxes to Pennsylvania","Maryland had no constitution allowing taxes","Banks were exempt from all taxes under the Articles of Confederation"],answer:0,entryId:"mcculloch-v-maryland",explanation:"Marshall held that the federal government, “though limited in its powers, is supreme within its sphere of action.” If states could tax one federal instrument, “they may tax the mail; they may tax the mint.”"},{id:"er3-q4",context:"The Monroe Doctrine (1823)",prompt:"Why did John Quincy Adams reject Britain’s offer of a joint declaration?",options:["He feared it would limit future American expansion and suspected British imperial motives","He wanted to help Spain reconquer its colonies","Britain had demanded that the United States give up Florida","Congress had forbidden any treaty with Britain"],answer:0,entryId:"monroe-doctrine",explanation:"The proposed joint declaration became a statement by the United States alone, announced in Monroe’s annual message of December 2, 1823."},{id:"er3-q5",context:"The Missouri Compromise (1820)",prompt:"Which three parts made up the Missouri Compromise?",options:["Missouri admitted as a slave state, Maine as a free state, and no slavery north of 36°30′ in the rest of the Louisiana Purchase","Missouri and Maine both admitted as free states and slavery banned everywhere west of the Mississippi","Missouri divided in two, with slavery allowed in the southern half only","Slavery decided by popular vote in every new territory"],answer:0,entryId:"missouri-compromise",explanation:"Senator Jesse Thomas proposed the bargain and Henry Clay helped pass it, earning the name “the Great Compromiser.” The line held until the Kansas-Nebraska Act of 1854."}]},{id:"markets-and-freedom",shortTitle:"Markets & Freedom",number:4,title:"Markets, Slavery and Freedom",years:"1817–1850",subtitle:"Canals and markets, the spread of slavery, and the struggle against it",overview:"After 1815 a market revolution remade the nation. The Erie Canal linked the Great Lakes to New York City, while the cotton gin spread slavery across the South. Enslaved people resisted by escaping, helped by networks that would be called the Underground Railroad, and a growing antislavery movement demanded change. By the end of the 1820s, Andrew Jackson, the hero of New Orleans, was ready to lead a new democratic politics.",guidingQuestion:"How did the market revolution change American life, and how did it both spread slavery and strengthen the fight against it?",entryIds:["erie-canal","underground-railroad","abolitionism","andrew-jackson"],primarySourceChallenge:{id:"psc-markets-and-freedom",quote:"Before the passing away of the present generation, not a single Iroquois will be seen in this state.",speaker:"DeWitt Clinton",context:"Speech to the New-York Historical Society, 1811, by the future champion of the Erie Canal",prompt:"What does Clinton’s prediction reveal about the Erie Canal era?",options:["Canal building and settlement went hand in hand with the dispossession of the Haudenosaunee nations.","The canal was built by Iroquois workers who then moved west.","Clinton opposed the canal because it crossed Native land.","The Iroquois had already left New York before 1811."],answer:0,entryId:"erie-canal",historicalNote:"The Erie Canalway’s own history says the canal boom “dramatically accelerated the dispossession” of Native peoples. Clinton was wrong, though: more members of the Six Nations live in New York today than at the end of the Revolution."},timeline:[{id:"t4-dig",label:"Construction of the Erie Canal begins at Rome, New York",date:"1817",sort:1817.5,entryId:"erie-canal"},{id:"t4-open",label:"The Erie Canal opens along its full length",date:"1825",sort:1825.8,entryId:"erie-canal"},{id:"t4-jackson",label:"Andrew Jackson wins the presidency",date:"1828",sort:1828.9,entryId:"andrew-jackson"},{id:"t4-liberator",label:"William Lloyd Garrison launches The Liberator",date:"1831",sort:1831.05,entryId:"abolitionism"},{id:"t4-aass",label:"The American Anti-Slavery Society is founded",date:"1833",sort:1833.9,entryId:"abolitionism"},{id:"t4-fsa",label:"The Fugitive Slave Act makes helping freedom seekers more dangerous",date:"1850",sort:1850.7,entryId:"underground-railroad"}],reflection:{modelAnswer:"The Erie Canal cut shipping costs by 90 percent, sent Midwestern grain east and settlers west, and made New York City the nation’s commercial center, while towns along the canal grew rapidly. The same market revolution increased demand for cotton: Eli Whitney’s gin let planters expand production, and the enslaved population grew from under 700,000 in 1790 to more than 1.5 million by 1820. Yet the new routes of commerce also carried ideas, and the canal corridor became a seedbed for abolitionism and other reforms. Enslaved people freed themselves by escape, with help from free and enslaved Black people and white allies, and by the 1830s abolitionists were demanding immediate emancipation.",keyPoints:["The Erie Canal and the transportation revolution","Cotton, the gin and the growth of slavery","Freedom seekers and the Underground Railroad","From gradual emancipation to immediatism"]},deepDive:[{url:"https://www.youtube.com/watch?v=RNftCCwAol0",title:"The Market Revolution: Crash Course US History #12",channel:"CrashCourse",views:3512795,length:"14:11",checked:t},{url:"https://www.youtube.com/watch?v=Iqfe7grWuNU",title:"Reflections on the Erie Canal (full documentary)",channel:"WMHT",views:9018,length:"56:23",checked:t}],quiz:[{id:"er4-q1",context:"The Erie Canal",prompt:"By how much did the Erie Canal cut the cost of shipping compared with ox-drawn wagons?",options:["About 90 percent","About 10 percent","About half","It made shipping more expensive but faster"],answer:0,entryId:"erie-canal",explanation:"Packet boats also carried passengers from Albany to Buffalo in five days instead of two weeks by stagecoach, and the canal repaid its $7 million cost within ten years."},{id:"er4-q2",context:"The Erie Canal",prompt:"Why was the Erie Canal called the “Mother of Cities”?",options:["So many towns grew up along it; Syracuse, Rochester and Buffalo quadrupled in population between 1830 and 1850","It was paid for by the cities of New York State","Its builders lived in cities they built themselves","It ended in every major city of the Northeast"],answer:0,entryId:"erie-canal",explanation:"The canal opened the interior to settlement and made New York City the nation’s busiest port and largest city."},{id:"er4-q3",context:"The Underground Railroad",prompt:"Why does the National Park Service prefer the term “freedom seeker” to “fugitive” or “runaway”?",options:["Those terms reflect how slaveholding society saw escape and take away individual agency","Escapes were legal, so “fugitive” is inaccurate","“Freedom seeker” was the official term used in the 1850 law","The other words were never used in the nineteenth century"],answer:0,entryId:"underground-railroad",explanation:"The Park Service also notes there is no universal consensus: some historians keep “fugitive” to stress that people who freed themselves broke the law."},{id:"er4-q4",context:"The Underground Railroad",prompt:"How did the Fugitive Slave Act of 1850 pay the federal commissioners who decided cases?",options:["$10 for ruling a captive enslaved, only $5 for ruling the person free","The same fee in every case","Nothing; they were unpaid volunteers","A share of the reward offered by the enslaver"],answer:0,entryId:"underground-railroad",explanation:"The American Yawp writes that the law “fostered corruption and the enslavement of free Black northerners,” and many Black northerners fled to Canada."},{id:"er4-q5",context:"Andrew Jackson",prompt:"What happened in the presidential election of 1824?",options:["Jackson led the vote but lost when the House chose the president","Jackson won in a landslide","Jackson did not run","The election was cancelled because of the Missouri crisis"],answer:0,entryId:"andrew-jackson",explanation:"Jackson lost in the House in 1824 despite leading the vote, then won in 1828 by 178 electoral votes to 83."}]}],finalExam:[{id:"er-final-1",context:"Module 1 · A Government Invented",prompt:"Which branch did Article I of the Constitution create first?",options:["Congress","The presidency","The Supreme Court","The cabinet"],answer:0,entryId:"congress",explanation:"Article I vests “All legislative Powers” in a Congress of a Senate and a House of Representatives; the presidency comes in Article II and the courts in Article III."},{id:"er-final-2",context:"Module 1 · A Government Invented",prompt:"Which constitutional amendment, ratified in 1804, required electors to vote separately for president and vice president?",options:["The Twelfth","The Tenth","The Fourteenth","The Twenty-second"],answer:0,entryId:"election-of-1800",explanation:"The Twelfth Amendment followed the Jefferson–Burr tie of 1800 and was designed around the way parties actually worked."},{id:"er-final-3",context:"Module 1 · A Government Invented",prompt:"Who persuaded Abraham Lincoln to proclaim a national Thanksgiving in 1863?",options:["Sarah Josepha Hale, editor of Godey’s Lady’s Book","Abigail Adams","Harriet Beecher Stowe","Dolley Madison"],answer:0,entryId:"thanksgiving",explanation:"Hale asked Lincoln on September 28, 1863, to make Thanksgiving “a National and fixed Union Festival.” His proclamation followed on October 3."},{id:"er-final-4",context:"Module 2 · Jefferson’s Republic",prompt:"How long did John Marshall serve as Chief Justice?",options:["More than thirty-four years, from 1801 to 1835","Eight years","Twelve years","Until the end of the War of 1812"],answer:0,entryId:"john-marshall",explanation:"Adams appointed Marshall weeks before leaving office. His leadership, the Court’s own history says, was “central to the development of its prominent role in American government.”"},{id:"er-final-5",context:"Module 2 · Jefferson’s Republic",prompt:"How large was the Louisiana Purchase?",options:["About 828,000 square miles, doubling the size of the country","About the size of New England","Only the city of New Orleans","The land between the Appalachians and the Mississippi"],answer:0,entryId:"louisiana-purchase",explanation:"The territory stretched from the Mississippi to the Rocky Mountains and covered all or part of fifteen present-day states."},{id:"er-final-6",context:"Module 2 · Jefferson’s Republic",prompt:"What happened to York, the man enslaved by William Clark, after the expedition?",options:["He was denied his payment and his freedom","He was freed and given land by Congress","He became governor of the Missouri Territory","He stayed at Fort Clatsop"],answer:0,entryId:"lewis-and-clark-expedition",explanation:"The National Park Service calls York “an American explorer who made important contributions” and likely the first African American to cross the continent."},{id:"er-final-7",context:"Module 3 · War and Nation",prompt:"What did Francis Scott Key witness that inspired “The Star-Spangled Banner”?",options:["The British bombardment of Fort McHenry at Baltimore","The burning of Washington","The Battle of New Orleans","The Battle of Lake Erie"],answer:0,entryId:"war-of-1812",explanation:"Fort McHenry withstood the British fleet in September 1814. Sources differ on whether the bombardment lasted 25 or 27 hours."},{id:"er-final-8",context:"Module 3 · War and Nation",prompt:"Which clause of the Constitution did Marshall rely on to uphold the national bank?",options:["The necessary and proper clause","The commerce clause alone","The Tenth Amendment","The fugitive slave clause"],answer:0,entryId:"mcculloch-v-maryland",explanation:"“Let the end be legitimate, let it be within the scope of the constitution, and all means which are appropriate … are constitutional.”"},{id:"er-final-9",context:"Module 4 · Markets and Freedom",prompt:"Who was the Erie Canal’s “most persistent and effective champion”?",options:["DeWitt Clinton","Andrew Jackson","Robert Fulton","Henry Clay"],answer:0,entryId:"erie-canal",explanation:"Clinton, a former U.S. senator and mayor of New York City, led the political fight and rode the first boat along the whole canal in 1825."},{id:"er-final-10",context:"Module 4 · Markets and Freedom",prompt:"Who said “I never ran my train off the track and I never lost a passenger”?",options:["Harriet Tubman","Frederick Douglass","William Still","Sojourner Truth"],answer:0,entryId:"underground-railroad",explanation:"Tubman was a conductor of the Underground Railroad for eight years and brought about 70 people, including her parents, to freedom in the 1850s."}]}];e.s(["V",0,n,"j",0,function(e){return n.find(t=>t.id===e)}],97677)}]);